    "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"Inter, system-ui, sans-serif\" role=\"img\" aria-label=\"One method, three plans\"><defs><marker id=\"bkr34bull\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#22c55e\"/></marker><marker id=\"bkr34bear\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#ef4444\"/></marker><marker id=\"bkr34lab\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#94a3b8\"/></marker><marker id=\"bkr34acc\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#f59e0b\"/></marker><marker id=\"bkr34tl\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"#a78bfa\"/></marker></defs><text x=\"20\" y=\"26\" font-size=\"15\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">One method, three plans</text><rect x=\"98\" y=\"58\" width=\"168\" height=\"26\" fill=\"#94a3b822\" stroke=\"#94a3b8\" stroke-width=\"1\" rx=\"4\"/><text x=\"182\" y=\"75\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"middle\" font-weight=\"700\">Long-term investor</text><rect x=\"270\" y=\"58\" width=\"168\" height=\"26\" fill=\"#f59e0b22\" stroke=\"#f59e0b\" stroke-width=\"1\" rx=\"4\"/><text x=\"354\" y=\"75\" font-size=\"11\" fill=\"#f59e0b\" text-anchor=\"middle\" font-weight=\"700\">Swing trader</text><rect x=\"442\" y=\"58\" width=\"168\" height=\"26\" fill=\"#22c55e22\" stroke=\"#22c55e\" stroke-width=\"1\" rx=\"4\"/><text x=\"526\" y=\"75\" font-size=\"11\" fill=\"#22c55e\" text-anchor=\"middle\" font-weight=\"700\">Day trader</text><line x1=\"24\" y1=\"86\" x2=\"612\" y2=\"86\" stroke=\"#94a3b8\" stroke-width=\"0.6\" opacity=\"0.5\"/><text x=\"24\" y=\"104\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">Chart</text><text x=\"104\" y=\"102\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Weekly</text><text x=\"276\" y=\"102\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Daily (maybe hourly)</text><text x=\"448\" y=\"102\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Daily zones, 5-min / hourly</text><text x=\"448\" y=\"115\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">exits</text><line x1=\"24\" y1=\"130\" x2=\"612\" y2=\"130\" stroke=\"#94a3b8\" stroke-width=\"0.6\" opacity=\"0.5\"/><text x=\"24\" y=\"148\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">Setup</text><text x=\"104\" y=\"146\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Buy above weekly demand; hedge</text><text x=\"104\" y=\"159\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">or sell at supply</text><text x=\"276\" y=\"146\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Trend: rejection candle in</text><text x=\"276\" y=\"159\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">zone. Counter: strong zone</text><text x=\"448\" y=\"146\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Strong fresh daily zone; gap</text><text x=\"448\" y=\"159\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">through a zone</text><line x1=\"24\" y1=\"174\" x2=\"612\" y2=\"174\" stroke=\"#94a3b8\" stroke-width=\"0.6\" opacity=\"0.5\"/><text x=\"24\" y=\"192\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">Stop</text><text x=\"104\" y=\"190\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Below the demand zone (exit on</text><text x=\"104\" y=\"203\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">a break)</text><text x=\"276\" y=\"190\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">A few cents beyond the zone</text><text x=\"448\" y=\"190\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Zone edge; gap trade: low/high</text><text x=\"448\" y=\"203\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">of day</text><line x1=\"24\" y1=\"218\" x2=\"612\" y2=\"218\" stroke=\"#94a3b8\" stroke-width=\"0.6\" opacity=\"0.5\"/><text x=\"24\" y=\"236\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">Min. R:R</text><text x=\"104\" y=\"234\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">-</text><text x=\"276\" y=\"234\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">maybe 5:1</text><text x=\"448\" y=\"234\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">at least 3:1</text><line x1=\"24\" y1=\"262\" x2=\"612\" y2=\"262\" stroke=\"#94a3b8\" stroke-width=\"0.6\" opacity=\"0.5\"/><text x=\"24\" y=\"280\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">Watch list</text><text x=\"104\" y=\"278\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Fundamentals first</text><text x=\"276\" y=\"278\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">Options with open interest &gt;</text><text x=\"276\" y=\"291\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">10,000</text><text x=\"448\" y=\"278\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">ATR &gt; 3% of price, 10M+ shares</text><text x=\"448\" y=\"291\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">a day</text><line x1=\"24\" y1=\"306\" x2=\"612\" y2=\"306\" stroke=\"#94a3b8\" stroke-width=\"0.6\" opacity=\"0.5\"/><text x=\"24\" y=\"324\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-weight=\"700\">Time</text><text x=\"104\" y=\"322\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">About 15 minutes a day</text><text x=\"276\" y=\"322\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">-</text><text x=\"448\" y=\"322\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">e.g. 4 hours from the open</text></svg>",
