"10\" fill=\"#94a3b8\" text-anchor=\"end\">-$200</text><text x=\"64\" y=\"279.3\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"end\">-$300</text><text x=\"94.2\" y=\"327\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"middle\">$5</text><text x=\"165\" y=\"327\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"middle\">$6</text><text x=\"235.9\" y=\"327\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"middle\">$7</text><text x=\"306.8\" y=\"327\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"middle\">$8</text><text x=\"377.7\" y=\"327\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"middle\">$9</text><text x=\"416\" y=\"342\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"end\" font-weight=\"600\">Alcoa price at expiry</text><path d=\"M87.1,293.6 L398.9,76.4\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-dasharray=\"7 4\"/><path d=\"M87.1,144 L306.8,144 L398.9,79.8\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"377.7\" cy=\"91.2\" r=\"4\" fill=\"#ef4444\" stroke=\"none\" stroke-width=\"1.5\"/><text x=\"369.7\" y=\"85.2\" font-size=\"10\" fill=\"#ef4444\" text-anchor=\"end\" font-weight=\"700\">+$73</text><circle cx=\"377.7\" cy=\"94.7\" r=\"4\" fill=\"#22c55e\" stroke=\"none\" stroke-width=\"1.5\"/><text x=\"385.7\" y=\"108.7\" font-size=\"10\" fill=\"#22c55e\" text-anchor=\"start\" font-weight=\"700\">+$66</text><circle cx=\"271.3\" cy=\"165.2\" r=\"4\" fill=\"#ef4444\" stroke=\"none\" stroke-width=\"1.5\"/><text x=\"279.3\" y=\"169.2\" font-size=\"10\" fill=\"#ef4444\" text-anchor=\"start\" font-weight=\"700\">-$77</text><circle cx=\"271.3\" cy=\"144\" r=\"4\" fill=\"#22c55e\" stroke=\"none\" stroke-width=\"1.5\"/><text x=\"279.3\" y=\"136\" font-size=\"10\" fill=\"#22c55e\" text-anchor=\"start\" font-weight=\"700\">-$34</text><circle cx=\"94.2\" cy=\"288.6\" r=\"4\" fill=\"#ef4444\" stroke=\"none\" stroke-width=\"1.5\"/><text x=\"102.2\" y=\"292.6\" font-size=\"10\" fill=\"#ef4444\" text-anchor=\"start\" font-weight=\"700\">-$327 (gap to $5)</text><circle cx=\"94.2\" cy=\"144\" r=\"4\" fill=\"#22c55e\" stroke=\"none\" stroke-width=\"1.5\"/><text x=\"102.2\" y=\"136\" font-size=\"10\" fill=\"#22c55e\" text-anchor=\"start\" font-weight=\"700\">-$34</text><rect x=\"440\" y=\"62\" width=\"190\" height=\"248\" fill=\"#94a3b812\" stroke=\"#94a3b8\" stroke-width=\"1\" rx=\"8\"/><line x1=\"452\" y1=\"84\" x2=\"476\" y2=\"84\" stroke=\"#ef4444\" stroke-width=\"2.2\" stroke-dasharray=\"7 4\"/><text x=\"482\" y=\"88\" font-size=\"11\" fill=\"#ef4444\" text-anchor=\"start\" font-weight=\"700\">100 shares at $8.27</text><text x=\"452\" y=\"104\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">loss keeps growing; a stop at</text><text x=\"452\" y=\"117\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">$7.50 is useless on an</text><text x=\"452\" y=\"130\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">overnight gap to $5</text><line x1=\"452\" y1=\"156\" x2=\"476\" y2=\"156\" stroke=\"#22c55e\" stroke-width=\"2.6\"/><text x=\"482\" y=\"160\" font-size=\"11\" fill=\"#22c55e\" text-anchor=\"start\" font-weight=\"700\">1 call, $8 strike, $0.34</text><text x=\"452\" y=\"176\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">costs $34; that is the most</text><text x=\"452\" y=\"189\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">it can ever lose. At $9 it</text><text x=\"452\" y=\"202\" font-size=\"10\" fill=\"#94a3b8\" text-anchor=\"start\">makes $66 vs. $73.</text><text x=\"452\" y=\"228\" font-size=\"10\" fill=\"#f59e0b\" text-anchor=\"start\">Stock + $8 put ($0.07 = $7)</text><text x=\"452\" y=\"241\" font-size=\"10\" fill=\"#f59e0b\" text-anchor=\"start\">gives the same shape:</text><text x=\"452\" y=\"254\" font-size=\"10\" fill=\"#f59e0b\" text-anchor=\"start\">max loss $27 + $7 = $34.</text><text x=\"452\" y=\"280\" font-size=\"9.5\" fill=\"#94a3b8\" text-anchor=\"start\">Stock losses computed from</text><text x=\"452\" y=\"292\" font-size=\"9.5\" fill=\"#94a3b8\" text-anchor=\"start\">$8.27; the book quotes $50/$300.</text><text x=\"20\" y=\"350\" font-size=\"11\" fill=\"#94a3b8\" text-anchor=\"start\" font-style=\"italic\">Payoff at expiry, before commissions.</text></svg>",
